insert into public.events (id, slug, title_fr, title_en, description_fr, description_en, location, starts_at, ends_at, cover_url, cover_alt, cover_focus, theme, featured, featured_order, stats, tags, content_fr, content_en, social_links, status)
values ($q$43a17a25-6983-52f2-8122-7085e4aa2661$q$, $q$octobre-rose-2026$q$, $q$Octobre Rose 2026 — Ensemble sensibilisons, ensemble agissons$q$, $q$Pink October 2026 — Raising awareness together$q$, $q$Une après-midi de Zumba, d'échanges avec des professionnelles de santé et de solidarité autour de la prévention du cancer du sein, avec Aga Sport.$q$, $q$An afternoon of Zumba, talks with health professionals and solidarity around breast cancer prevention, with Aga Sport.$q$, $q$Aga Sport, Tlemcen$q$, $q$2026-10-24 16:00+01$q$, $q$2026-10-24 20:00+01$q$, $q$https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/173f7d99-0694-5daf-b08c-e6d18b99dc3f.webp$q$, $q$Arche de ballons roses et séance de Zumba sur le terrain d'Aga Sport$q$, $q${"x": 50, "y": 45}$q$::jsonb, $q${"primary": "#d6336c", "accent": "#ef4a6c", "background": "#ffffff", "text": "#231f20", "font": "sans", "radius": "soft", "header": "gradient", "headerLayout": "fullBleed", "overlay": 40}$q$::jsonb, true, 1, $q$[{"value": "1", "label_fr": "séance de Zumba solidaire", "label_en": "solidarity Zumba session", "icon": "activity"}, {"value": "Aga Sport", "label_fr": "partenaire de l'événement", "label_en": "event partner", "icon": "heart"}]$q$::jsonb, array[$q$Sensibilisation$q$, $q$Octobre Rose$q$, $q$Santé de la femme$q$]::text[], $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "À l'occasion d'"}, {"type": "text", "text": "Octobre Rose", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", le Life Savers Club et "}, {"type": "text", "text": "Aga Sport", "marks": [{"type": "bold"}]}, {"type": "text", "text": " ont donné rendez-vous au public pour une après-midi placée sous le signe de la solidarité, du bien-être et de la sensibilisation au cancer du sein."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Au programme"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Une séance de Zumba dans une ambiance dynamique et conviviale."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Des interventions de professionnelles de santé pour informer sur le dépistage et la prévention."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Un moment de partage et d'échange autour d'une cause qui nous concerne toutes et tous."}]}]}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/dc507db5-22b6-599f-99b9-420e5d083e9e.webp", "alt": "Octobre Rose 2026 — photo 1", "caption": "", "mediaId": "dc507db5-22b6-599f-99b9-420e5d083e9e"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/6eac28c3-c347-5bf4-be14-eab21d746b74.webp", "alt": "Octobre Rose 2026 — photo 2", "caption": "", "mediaId": "6eac28c3-c347-5bf4-be14-eab21d746b74"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/fb4173c3-4f86-508c-820c-13ba3034bdcc.webp", "alt": "Octobre Rose 2026 — photo 3", "caption": "", "mediaId": "fb4173c3-4f86-508c-820c-13ba3034bdcc"}], "layout": "grid", "columns": 3}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Une journée à retenir"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Des kits de sensibilisation préparés par nos membres, un terrain décoré de rose, de la musique et beaucoup d'énergie : à travers le sport et les échanges, nous avons partagé bien plus qu'un événement, un engagement commun pour une cause qui nous tient à cœur."}]}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/c96249df-3a09-5f70-b509-fbf582d6f797-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/3d13de6a-d375-5d12-aa7a-15c92688242f.webp", "title": "Octobre Rose — retour en vidéo", "caption": "", "loop": false}}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/3d13de6a-d375-5d12-aa7a-15c92688242f.webp", "alt": "Octobre Rose 2026 — photo 4", "caption": "", "mediaId": "3d13de6a-d375-5d12-aa7a-15c92688242f"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/8e57e2cc-a6d9-542e-8d63-514e4ad11352.webp", "alt": "Octobre Rose 2026 — photo 5", "caption": "", "mediaId": "8e57e2cc-a6d9-542e-8d63-514e4ad11352"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/2489c2fe-0987-5d7e-86d1-d0f2383c3998.webp", "alt": "Octobre Rose 2026 — photo 6", "caption": "", "mediaId": "2489c2fe-0987-5d7e-86d1-d0f2383c3998"}], "layout": "grid", "columns": 3}}, {"type": "callout", "attrs": {"tone": "heart", "color": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La prévention peut sauver des vies. Un dépistage précoce du cancer du sein augmente fortement les chances de guérison : parlez-en à votre médecin."}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Merci à Aga Sport, à nos intervenantes, à nos partenaires et à toutes les personnes qui ont contribué à la réussite de cette journée. Ensemble, faisons de la sensibilisation une force."}]}, {"type": "image", "attrs": {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/dd6d5a04-280e-58e0-8a80-3bc9c3f1856b.webp", "width": "50", "alt": "Octobre Rose 2026 — photo 7", "caption": "", "mediaId": "dd6d5a04-280e-58e0-8a80-3bc9c3f1856b", "align": "center", "rounded": true, "shadow": false, "border": false}}]}$q$::jsonb, $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "For "}, {"type": "text", "text": "Pink October", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", Life Savers Club and "}, {"type": "text", "text": "Aga Sport", "marks": [{"type": "bold"}]}, {"type": "text", "text": " invited the public to an afternoon of solidarity, well-being and breast cancer awareness."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "On the programme"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A Zumba session in a lively, friendly atmosphere."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Talks by health professionals about screening and prevention."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Time to share and talk about a cause that concerns us all."}]}]}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/dc507db5-22b6-599f-99b9-420e5d083e9e.webp", "alt": "Pink October 2026 — photo 1", "caption": "", "mediaId": "dc507db5-22b6-599f-99b9-420e5d083e9e"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/6eac28c3-c347-5bf4-be14-eab21d746b74.webp", "alt": "Pink October 2026 — photo 2", "caption": "", "mediaId": "6eac28c3-c347-5bf4-be14-eab21d746b74"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/fb4173c3-4f86-508c-820c-13ba3034bdcc.webp", "alt": "Pink October 2026 — photo 3", "caption": "", "mediaId": "fb4173c3-4f86-508c-820c-13ba3034bdcc"}], "layout": "grid", "columns": 3}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "A day to remember"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Awareness kits prepared by our members, a pitch decorated in pink, music and lots of energy: through sport and conversation we shared much more than an event — a common commitment to a cause close to our hearts."}]}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/c96249df-3a09-5f70-b509-fbf582d6f797-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/3d13de6a-d375-5d12-aa7a-15c92688242f.webp", "title": "Pink October — video recap", "caption": "", "loop": false}}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/3d13de6a-d375-5d12-aa7a-15c92688242f.webp", "alt": "Pink October 2026 — photo 4", "caption": "", "mediaId": "3d13de6a-d375-5d12-aa7a-15c92688242f"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/8e57e2cc-a6d9-542e-8d63-514e4ad11352.webp", "alt": "Pink October 2026 — photo 5", "caption": "", "mediaId": "8e57e2cc-a6d9-542e-8d63-514e4ad11352"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/2489c2fe-0987-5d7e-86d1-d0f2383c3998.webp", "alt": "Pink October 2026 — photo 6", "caption": "", "mediaId": "2489c2fe-0987-5d7e-86d1-d0f2383c3998"}], "layout": "grid", "columns": 3}}, {"type": "callout", "attrs": {"tone": "heart", "color": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Prevention saves lives. Early breast cancer screening greatly improves the chances of recovery — talk to your doctor about it."}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Thank you to Aga Sport, our speakers, our partners and everyone who helped make this day a success. Together, let's turn awareness into strength."}]}, {"type": "image", "attrs": {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/43a17a25-6983-52f2-8122-7085e4aa2661/dd6d5a04-280e-58e0-8a80-3bc9c3f1856b.webp", "width": "50", "alt": "Pink October 2026 — photo 7", "caption": "", "mediaId": "dd6d5a04-280e-58e0-8a80-3bc9c3f1856b", "align": "center", "rounded": true, "shadow": false, "border": false}}]}$q$::jsonb, $q${"instagram": "https://www.instagram.com/reel/DfPlLQ5yqDJ/"}$q$::jsonb, 'draft')
on conflict (slug) do nothing;

insert into public.events (id, slug, title_fr, title_en, description_fr, description_en, location, starts_at, ends_at, cover_url, cover_alt, cover_focus, theme, featured, featured_order, stats, tags, content_fr, content_en, social_links, status)
values ($q$2a9e27ff-aaba-5a72-9cb6-e29a497cc720$q$, $q$ceremonie-promo-medecine-2019-2026$q$, $q$Cérémonie de remise des diplômes — Promotion de médecine 2019/2026$q$, $q$Graduation ceremony — Medicine class of 2019/2026$q$, $q$Retour en images sur la cérémonie qui a célébré la réussite et le parcours de nos nouveaux médecins.$q$, $q$Looking back at the ceremony that celebrated the success and journey of our new doctors.$q$, $q$Hôtel Alcazar, Tlemcen$q$, $q$2026-09-26 10:00+01$q$, null, $q$https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/2bf6baeb-1aaf-5c4b-865d-a7584984f25f.webp$q$, $q$Les diplômés de la promotion 2019/2026 en toge dans la salle de cérémonie$q$, $q${"x": 50, "y": 40}$q$::jsonb, $q${}$q$::jsonb, false, 0, $q$[{"value": "2019 → 2026", "label_fr": "sept années d'études", "label_en": "seven years of study", "icon": "award"}]$q$::jsonb, array[$q$Cérémonie$q$, $q$Promotion 2019/2026$q$]::text[], $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sept années d'études, de gardes, d'examens et d'entraide… La promotion de médecine "}, {"type": "text", "text": "2019/2026", "marks": [{"type": "bold"}]}, {"type": "text", "text": " a reçu ses diplômes lors d'une magnifique cérémonie, entourée de ses familles, de ses enseignants et de ses amis."}]}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/739111a0-1558-5227-8262-877e724cb4e8-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/2bf6baeb-1aaf-5c4b-865d-a7584984f25f.webp", "title": "Promotion 2019/2026 — Yes we did it", "caption": "", "loop": false}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Retour en images"}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/e70d49fc-83c1-5862-9cc6-6a4d09998d5a.webp", "alt": "Cérémonie de remise des diplômes — photo 1", "caption": "", "mediaId": "e70d49fc-83c1-5862-9cc6-6a4d09998d5a"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/17a29307-da28-5b0e-8521-8ee702914d31.webp", "alt": "Cérémonie de remise des diplômes — photo 2", "caption": "", "mediaId": "17a29307-da28-5b0e-8521-8ee702914d31"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/e4e8e731-2437-5ca0-9c95-f1fe327998e5.webp", "alt": "Cérémonie de remise des diplômes — photo 3", "caption": "", "mediaId": "e4e8e731-2437-5ca0-9c95-f1fe327998e5"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/376e67ee-cf5f-59ca-8dca-fc874604dcdd.webp", "alt": "Cérémonie de remise des diplômes — photo 4", "caption": "", "mediaId": "376e67ee-cf5f-59ca-8dca-fc874604dcdd"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/d4da5aa7-2729-53cf-8773-e17220db4edf.webp", "alt": "Cérémonie de remise des diplômes — photo 5", "caption": "", "mediaId": "d4da5aa7-2729-53cf-8773-e17220db4edf"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/408287d8-6b2b-5f07-8af3-3502d253cfb0.webp", "alt": "Cérémonie de remise des diplômes — photo 6", "caption": "", "mediaId": "408287d8-6b2b-5f07-8af3-3502d253cfb0"}], "layout": "grid", "columns": 3}}, {"type": "paragraph", "content": [{"type": "text", "text": "Félicitations à toutes et à tous pour cette belle réussite. Que cette nouvelle étape soit le début d'une grande aventure professionnelle, au service des patients."}]}, {"type": "callout", "attrs": {"tone": "info", "color": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Organisation : Ahmed Barkat, avec le Life Savers Club. Vidéo : Studio Nebia. Photos : Bekhechi Studio. Lieu : Hôtel Alcazar, Tlemcen."}]}]}]}$q$::jsonb, $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Seven years of study, night shifts, exams and mutual support… The medicine class of "}, {"type": "text", "text": "2019/2026", "marks": [{"type": "bold"}]}, {"type": "text", "text": " received their diplomas at a beautiful ceremony, surrounded by family, teachers and friends."}]}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/739111a0-1558-5227-8262-877e724cb4e8-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/2bf6baeb-1aaf-5c4b-865d-a7584984f25f.webp", "title": "Class of 2019/2026 — Yes we did it", "caption": "", "loop": false}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "In pictures"}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/e70d49fc-83c1-5862-9cc6-6a4d09998d5a.webp", "alt": "Graduation ceremony — photo 1", "caption": "", "mediaId": "e70d49fc-83c1-5862-9cc6-6a4d09998d5a"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/17a29307-da28-5b0e-8521-8ee702914d31.webp", "alt": "Graduation ceremony — photo 2", "caption": "", "mediaId": "17a29307-da28-5b0e-8521-8ee702914d31"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/e4e8e731-2437-5ca0-9c95-f1fe327998e5.webp", "alt": "Graduation ceremony — photo 3", "caption": "", "mediaId": "e4e8e731-2437-5ca0-9c95-f1fe327998e5"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/376e67ee-cf5f-59ca-8dca-fc874604dcdd.webp", "alt": "Graduation ceremony — photo 4", "caption": "", "mediaId": "376e67ee-cf5f-59ca-8dca-fc874604dcdd"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/d4da5aa7-2729-53cf-8773-e17220db4edf.webp", "alt": "Graduation ceremony — photo 5", "caption": "", "mediaId": "d4da5aa7-2729-53cf-8773-e17220db4edf"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/2a9e27ff-aaba-5a72-9cb6-e29a497cc720/408287d8-6b2b-5f07-8af3-3502d253cfb0.webp", "alt": "Graduation ceremony — photo 6", "caption": "", "mediaId": "408287d8-6b2b-5f07-8af3-3502d253cfb0"}], "layout": "grid", "columns": 3}}, {"type": "paragraph", "content": [{"type": "text", "text": "Congratulations to every graduate. May this new chapter be the start of a great professional adventure in the service of patients."}]}, {"type": "callout", "attrs": {"tone": "info", "color": null}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Organised by Ahmed Barkat with Life Savers Club. Video: Studio Nebia. Photos: Bekhechi Studio. Venue: Hôtel Alcazar, Tlemcen."}]}]}]}$q$::jsonb, $q${"instagram": "https://www.instagram.com/reel/DdzOOmlqK7i/"}$q$::jsonb, 'draft')
