values ($q$0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77$q$, $q$biolife-2026$q$, $q$BioLife — Là où santé, nutrition et sport se rencontrent$q$, $q$BioLife — Where health, nutrition and sport meet$q$, $q$Une journée immersive à la Faculté de médecine : conférences le matin, ateliers sport, nutrition et automédication l'après-midi.$q$, $q$An immersive day at the Faculty of Medicine: talks in the morning, sport, nutrition and self-medication workshops in the afternoon.$q$, $q$Faculté de médecine Dr Benzerdjeb Benaouda, Tlemcen$q$, $q$2026-05-12 09:00+01$q$, $q$2026-05-12 17:00+01$q$, $q$https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/f5fe4c8d-2075-5dd7-aff3-d05c4f5119ef.webp$q$, $q$L'équipe BioLife réunie devant les stands dans la cour de la faculté$q$, $q${"x": 50, "y": 45}$q$::jsonb, $q${"primary": "#2f7a14", "accent": "#6ebd45", "background": "#ffffff", "text": "#231f20", "font": "sans", "radius": "round", "header": "solid", "headerLayout": "fullBleed", "overlay": 45}$q$::jsonb, true, 2, $q$[{"value": "3", "label_fr": "univers : nutrition, sport, bien-être", "label_en": "themes: nutrition, sport, well-being", "icon": "activity"}, {"value": "1", "label_fr": "journée immersive", "label_en": "immersive day", "icon": "calendar"}]$q$::jsonb, array[$q$Santé$q$, $q$Nutrition$q$, $q$Sport$q$, $q$Conférences$q$]::text[], $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Après une campagne « mystère » sur nos réseaux, le secret a été révélé : "}, {"type": "text", "text": "BioLife", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", une journée où nutrition, sport et soin de soi se rejoignent autour d'un même message — l'équilibre est la vraie clé du bien-être."}]}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/b613b63c-c1be-5159-9215-f079d7909ac3-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/d555512a-9d31-5612-bf81-5d3815054ffa-v2.webp", "title": "Le teaser BioLife", "caption": "", "loop": false}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Le programme"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Matin — cycle de conférences : ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "automédication, phytothérapie et toxicité des produits alimentaires, suivies d'échanges avec le public."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Après-midi — immersion pratique : ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "ateliers Sport & entraînement, Nutrition & alimentation, Automédication : bonnes pratiques."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Et aussi : ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "jeux, défis, stands de nos partenaires, cadeaux et surprises."}]}]}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/18d8c606-8077-5e49-89d8-d1edccb830b3.webp", "alt": "BioLife — photo 1", "caption": "", "mediaId": "18d8c606-8077-5e49-89d8-d1edccb830b3"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/649b9745-6dc3-5216-91fd-e0fcdfa7e6e2.webp", "alt": "BioLife — photo 2", "caption": "", "mediaId": "649b9745-6dc3-5216-91fd-e0fcdfa7e6e2"}], "layout": "grid", "columns": 2}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Les conférences"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Un grand merci à nos intervenants pour des conférences riches qui ont apporté connaissances, débats et sensibilisation à nos participants."}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/4a7906d6-b98f-5a3e-be37-61c74d995d17.webp", "alt": "BioLife — photo 3", "caption": "", "mediaId": "4a7906d6-b98f-5a3e-be37-61c74d995d17"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/0705f614-2f08-59ef-ba19-81fc294a3e7a.webp", "alt": "BioLife — photo 4", "caption": "", "mediaId": "0705f614-2f08-59ef-ba19-81fc294a3e7a"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/3369c84d-6707-5c45-8829-dc9f9ee47935.webp", "alt": "BioLife — photo 5", "caption": "", "mediaId": "3369c84d-6707-5c45-8829-dc9f9ee47935"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/d6c79450-da8f-5324-823c-48265263da28.webp", "alt": "BioLife — photo 6", "caption": "", "mediaId": "d6c79450-da8f-5324-823c-48265263da28"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/459e8d76-1f23-525e-a5de-c275e909783a.webp", "alt": "BioLife — photo 7", "caption": "", "mediaId": "459e8d76-1f23-525e-a5de-c275e909783a"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/b11684d3-8cef-5bb0-9d54-7b3f7c5e65c3.webp", "alt": "BioLife — photo 8", "caption": "", "mediaId": "b11684d3-8cef-5bb0-9d54-7b3f7c5e65c3"}], "layout": "grid", "columns": 3}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Ateliers, stands et jeux"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "