9-efe2-57ea-80f6-773a98813aa2.webp", "alt": "BioLife — photo 15", "caption": "", "mediaId": "bdc13619-efe2-57ea-80f6-773a98813aa2"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/1fe8c427-7e6c-51aa-87a4-aa320e472c52.webp", "alt": "BioLife — photo 16", "caption": "", "mediaId": "1fe8c427-7e6c-51aa-87a4-aa320e472c52"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/eb8e67bc-cf6b-55f6-b303-5cc91dd4b125.webp", "alt": "BioLife — photo 17", "caption": "", "mediaId": "eb8e67bc-cf6b-55f6-b303-5cc91dd4b125"}], "layout": "masonry", "columns": 3}}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/328f404e-42a1-5d14-ad09-24e5e257b453-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/bd152a8c-1947-5e8b-9fc0-bdc79c942800-v2.webp", "title": "BioLife — l'ambiance de la journée", "caption": "", "loop": false}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "L'équipe"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Derrière chaque événement réussi, il y a une équipe pleine de passion et d'énergie. Fiers de chaque membre et organisateur qui a fait de cette journée une expérience créée avec le cœur."}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/9fecaf22-f202-5b71-b731-248a94fe7f00.webp", "alt": "BioLife — photo 18", "caption": "", "mediaId": "9fecaf22-f202-5b71-b731-248a94fe7f00"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/be6fae96-4fb1-5657-ac88-d1382e04ce07.webp", "alt": "BioLife — photo 19", "caption": "", "mediaId": "be6fae96-4fb1-5657-ac88-d1382e04ce07"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/6cf70eaf-cf5e-54d7-9501-4941cfffc058.webp", "alt": "BioLife — photo 20", "caption": "", "mediaId": "6cf70eaf-cf5e-54d7-9501-4941cfffc058"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/9959e5c8-6734-5b0d-b441-40d1e27e5f6f.webp", "alt": "BioLife — photo 21", "caption": "", "mediaId": "9959e5c8-6734-5b0d-b441-40d1e27e5f6f"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/b8caed03-d2c3-57e0-9a25-d54979b2244a.webp", "alt": "BioLife — photo 22", "caption": "", "mediaId": "b8caed03-d2c3-57e0-9a25-d54979b2244a"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/9970ef57-9b38-53b7-add3-d8c3a076e515.webp", "alt": "BioLife — photo 23", "caption": "", "mediaId": "9970ef57-9b38-53b7-add3-d8c3a076e515"}], "layout": "grid", "columns": 3}}]}$q$::jsonb, $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "After a “mystery” campaign on our social media, the secret was out: "}, {"type": "text", "text": "BioLife", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", a day where nutrition, sport and self-care come together around one message — balance is the real key to well-being."}]}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/b613b63c-c1be-5159-9215-f079d7909ac3-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/d555512a-9d31-5612-bf81-5d3815054ffa-v2.webp", "title": "The BioLife teaser", "caption": "", "loop": false}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The programme"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Morning — talks: ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "self-medication, phytotherapy and food toxicity, followed by questions from the audience."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Afternoon — hands-on: ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "workshops on Sport & training, Nutrition & diet, and Self-medication good practice."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Also: ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "games, challenges, partner stands, gifts and surprises."}]}]}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/18d8c606-8077-5e49-89d8-d1edccb830b3.webp", "alt": "BioLife — photo 1", "caption": "", "mediaId": "18d8c606-8077-5e49-89d8-d1edccb830b3"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/649b9745-6dc3-5216-91fd-e0fcdfa7e6e2.webp", "alt": "BioLife — photo 2", "caption": "", "mediaId": "649b9745-6dc3-5216-91fd-e0fcdfa7e6e2"}], "layout": "grid", "columns": 2}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The talks"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A big thank you to our speakers for insightful talks that brought knowledge, discussion and awareness to our participants."}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/4a7906d6-b98f-5a3e-be37-61c74d995d17.webp", "alt": "BioLife — photo 3", "caption": "", "mediaId": "4a7906d6-b98f-5a3e-be37-61c74d995d17"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/0705f614-2f08-59ef-ba19-81fc294a3e7a.webp", "alt": "BioLife — photo 4", "caption": "", "mediaId": "0705f614-2f08-59ef-ba19-81fc294a3e7a"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/3369c84d-6707-5c45-8829-dc9f9ee47935.webp", "alt": "BioLife — photo 5", "caption": "", "mediaId": "3369c84d-6707-5c45-8829-dc9f9ee47935"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/d6c79450-da8f-5324-823c-48265263da28.webp", "alt": "BioLife — photo 6", "caption": "", "mediaId": "d6c79450-da8f-5324-823c-48265263da28"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/459e8d76-1f23-525e-a5de-c275e909783a.webp", "alt": "BioLife — photo 7", "caption": "", "mediaId": "459e8d76-1f23-525e-a5de-c275e909783a"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/0bbb0347-4d1c-5031-ac8b-c42fc5cd3c77/b11684d3-8cef-5bb0-9d54-7b3f7c5e65c3.webp", "alt": "BioLife — photo 8", "caption": "", "mediaId": "b11684d3-8cef-5bb0-9d54-7b3f7c5e65c3"}], "layout": "grid", "columns": 3}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Workshops, stands and games"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "All afternoon the faculty courtyard became a well-being village: sports challenges, nutrition stands, a handprint tree, skill games and meetings with our partners."}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxm