values ($q$d67c0099-9892-563d-8a83-ff8b6f635af8$q$, $q$khotwa-tour-2026$q$, $q$Khotwa Tour 2026 — Le club au plus grand salon de la jeunesse$q$, $q$Khotwa Tour 2026 — The club at Algeria's largest youth fair$q$, $q$Un stand, un atelier interactif et une intervention sur les bases du secourisme au Palais de la Culture de Tlemcen.$q$, $q$A stand, an interactive workshop and a talk on first-aid basics at the Palais de la Culture in Tlemcen.$q$, $q$Palais de la Culture, Tlemcen$q$, $q$2026-05-02 10:00+01$q$, null, $q$https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/96b08503-5e2a-542e-9f00-75cd87c15333.webp$q$, $q$Les membres du Life Savers Club devant leur stand au Khotwa Tour$q$, $q${"x": 50, "y": 45}$q$::jsonb, $q${}$q$::jsonb, false, 0, $q$[]$q$::jsonb, array[$q$Secourisme$q$, $q$Jeunesse$q$, $q$Salon$q$]::text[], $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Le Life Savers Club était fier de participer au "}, {"type": "text", "text": "Khotwa Tour 2026", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", le plus grand salon de la jeunesse en Algérie, au Palais de la Culture de Tlemcen."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Ce que nous avons proposé"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Un stand pour présenter le club, ses activités et ses valeurs."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Un atelier interactif mêlant sensibilisation et pratique, avec nos modèles anatomiques et nos supports « Médecine : les organes et les spécialités »."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Une courte conférence, donnée par une médecin, sur les bases du secourisme et la conduite à tenir face à une urgence."}]}]}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/5a9fbb3a-d9db-5f6a-bb89-5165881e2564.webp", "alt": "Khotwa Tour 2026 — photo 1", "caption": "", "mediaId": "5a9fbb3a-d9db-5f6a-bb89-5165881e2564"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/6620298f-2519-5217-8e89-08d5def7156a.webp", "alt": "Khotwa Tour 2026 — photo 2", "caption": "", "mediaId": "6620298f-2519-5217-8e89-08d5def7156a"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/7bf6d829-e12c-5324-8190-4c394be1b1bb.webp", "alt": "Khotwa Tour 2026 — photo 3", "caption": "", "mediaId": "7bf6d829-e12c-5324-8190-4c394be1b1bb"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/586477b4-ea9e-5fe1-a255-1050ad4f0199.webp", "alt": "Khotwa Tour 2026 — photo 4", "caption": "", "mediaId": "586477b4-ea9e-5fe1-a255-1050ad4f0199"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/a43c1cb0-6d4c-5a30-9b2c-ea7e5836d26c.webp", "alt": "Khotwa Tour 2026 — photo 5", "caption": "", "mediaId": "a43c1cb0-6d4c-5a30-9b2c-ea7e5836d26c"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/be368283-12fd-5333-996d-1d426f88f1ac.webp", "alt": "Khotwa Tour 2026 — photo 6", "caption": "", "mediaId": "be368283-12fd-5333-996d-1d426f88f1ac"}], "layout": "grid", "columns": 3}}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/aad003e3-8bd1-5efb-b7a3-bc476fe0e8b2-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/c626fdc1-e97a-5459-96ee-ef0863caae0f-v2.webp", "title": "Khotwa Tour 2026 en vidéo", "caption": "", "loop": false}}, {"type": "paragraph", "content": [{"type": "text", "text": "Des moments pleins d'enthousiasme, d'apprentissage et d'esprit d'équipe, qui renforcent notre engagement à diffuser la culture des premiers secours et à servir la communauté. Merci à tous nos membres présents !"}]}]}$q$::jsonb, $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Life Savers Club was proud to take part in "}, {"type": "text", "text": "Khotwa Tour 2026", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", Algeria's largest youth fair, at the Palais de la Culture in Tlemcen."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What we offered"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A stand presenting the club, its activities and its values."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "An interactive workshop combining awareness and practice, with our anatomical models and our “Medicine: organs and specialties” materials."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A short talk by a doctor on first-aid basics and what to do in an emergency."}]}]}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/5a9fbb3a-d9db-5f6a-bb89-5165881e2564.webp", "alt": "Khotwa Tour 2026 — photo 1", "caption": "", "mediaId": "5a9fbb3a-d9db-5f6a-bb89-5165881e2564"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/6620298f-2519-5217-8e89-08d5def7156a.webp", "alt": "Khotwa Tour 2026 — photo 2", "caption": "", "mediaId": "6620298f-2519-5217-8e89-08d5def7156a"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/7bf6d829-e12c-5324-8190-4c394be1b1bb.webp", "alt": "Khotwa Tour 2026 — photo 3", "caption": "", "mediaId": "7bf6d829-e12c-5324-8190-4c394be1b1bb"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/586477b4-ea9e-5fe1-a255-1050ad4f0199.webp", "alt": "Khotwa Tour 2026 — photo 4", "caption": "", "mediaId": "586477b4-ea9e-5fe1-a255-1050ad4f0199"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/a43c1cb0-6d4c-5a30-9b2c-ea7e5836d26c.webp", "alt": "Khotwa Tour 2026 — photo 5", "caption": "", "mediaId": "a43c1cb0-6d4c-5a30-9b2c-ea7e5836d26c"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/be368283-12fd-5333-996d-1d426f88f1ac.webp", "alt": "Khotwa Tour 2026 — photo 6", "caption": "", "mediaId": "be368283-12fd-5333-996d-1d426f88f1ac"}], "layout": "grid", "columns": 3}}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/aad003e3-8bd1-5efb-b7a3-bc476fe0e8b2-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/d67c0099-9892-563d-8a83-ff8b6f635af8/c626fdc1-e97a-5459-96ee-ef0863caae0f-v2.webp", "title": "Khotwa Tour 2026 on video", "caption": "", "loop": false}}, {"type": "paragraph", "content": [{"type": "text", "text": "Moments full of enthusiasm, learning and team spirit that strengthen our commitment to spreading first-aid culture and serving the community. Thank you to all our members who were there!"}]}]}$q$::jsonb, $q${"instagram": "https://www.instagram.com/p/DX2K5Q6jVOt/"}$q$::jsonb, 'draft')
