mediaId": "f68e2910-683a-51bb-a39e-af233e85ba29"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/9d4e8fa3-4f7c-52a9-b6c5-21d155c2b400/6fc3dec2-fb9f-5186-9c69-141f5b194992.webp", "alt": "Stitch It Up 3 — photo 22", "caption": "", "mediaId": "6fc3dec2-fb9f-5186-9c69-141f5b194992"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/9d4e8fa3-4f7c-52a9-b6c5-21d155c2b400/08d9412b-fe22-59b8-88e1-03dc7f135537.webp", "alt": "Stitch It Up 3 — photo 23", "caption": "", "mediaId": "08d9412b-fe22-59b8-88e1-03dc7f135537"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/9d4e8fa3-4f7c-52a9-b6c5-21d155c2b400/060156e7-bb2c-5b3e-a23c-2663d9dc9693.webp", "alt": "Stitch It Up 3 — photo 24", "caption": "", "mediaId": "060156e7-bb2c-5b3e-a23c-2663d9dc9693"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/9d4e8fa3-4f7c-52a9-b6c5-21d155c2b400/b65e0a3e-9ad5-5a40-bfee-033787a0bf3a.webp", "alt": "Stitch It Up 3 — photo 25", "caption": "", "mediaId": "b65e0a3e-9ad5-5a40-bfee-033787a0bf3a"}], "layout": "carousel", "columns": 3}}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/9d4e8fa3-4f7c-52a9-b6c5-21d155c2b400/b8be3a8b-86d5-53cb-a5d7-c3d9d126dc35.webp", "alt": "Stitch It Up 3 — photo 26", "caption": "", "mediaId": "b8be3a8b-86d5-53cb-a5d7-c3d9d126dc35"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/9d4e8fa3-4f7c-52a9-b6c5-21d155c2b400/5024fa2d-cf3b-52bd-b0b0-49a776dff448.webp", "alt": "Stitch It Up 3 — photo 27", "caption": "", "mediaId": "5024fa2d-cf3b-52bd-b0b0-49a776dff448"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/9d4e8fa3-4f7c-52a9-b6c5-21d155c2b400/29070c9c-5dab-5c5e-bd6c-fb06e812b7cf.webp", "alt": "Stitch It Up 3 — p