values ($q$6d70717a-61b3-53ab-b580-10f1509116c7$q$, $q$radio-tlemcen$q$, $q$Le club à l'antenne de Radio Tlemcen$q$, $q$The club on air at Radio Tlemcen$q$, $q$Une soirée derrière le micro de la radio régionale pour parler santé, science et engagement étudiant.$q$, $q$An evening behind the microphone of the regional radio to talk about health, science and student engagement.$q$, $q$Radio Tlemcen$q$, $q$2026-04-12 19:00+01$q$, null, $q$https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/6d70717a-61b3-53ab-b580-10f1509116c7/ffc96ce2-4f73-5503-8ced-5c384d8fd872.webp$q$, $q$Des membres du club en studio à Radio Tlemcen$q$, $q${"x": 40, "y": 50}$q$::jsonb, $q${}$q$::jsonb, false, 0, $q$[]$q$::jsonb, array[$q$Médias$q$, $q$Sensibilisation$q$]::text[], $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nous avons eu le plaisir de passer notre soirée dans les studios de "}, {"type": "text", "text": "Radio Tlemcen", "marks": [{"type": "bold"}]}, {"type": "text", "text": ". Une occasion incroyable pour le club de prendre le micro et de partager sa passion avec un public plus large."}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/6d70717a-61b3-53ab-b580-10f1509116c7/c97d6482-367c-5079-9a16-954c8e96856d.webp", "alt": "Le club à l'antenne de Radio Tlemcen — photo 1", "caption": "", "mediaId": "c97d6482-367c-5079-9a16-954c8e96856d"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/6d70717a-61b3-53ab-b580-10f1509116c7/290cfe87-ad4f-505c-a23a-ab612cc87314.webp", "alt": "Le club à l'antenne de Radio Tlemcen — photo 2", "caption": "", "mediaId": "290cfe87-ad4f-505c-a23a-ab612cc87314"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/6d70717a-61b3-53ab-b580-10f1509116c7/f00dd696-614c-5795-907e-7cd19a205fb8.webp", "alt": "Le club à l'antenne de Radio Tlemcen — photo 3", "caption": "", "mediaId": "f00dd696-614c-5795-907e-7cd19a205fb8"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/6d70717a-61b3-53ab-b580-10f1509116c7/b7eec27e-7b3d-5015-b5cb-f98548a3567a.webp", "alt": "Le club à l'antenne de Radio Tlemcen — photo 4", "caption": "", "mediaId": "b7eec27e-7b3d-5015-b5cb-f98548a3567a"}], "layout": "grid", "columns": 2}}, {"type": "paragraph", "content": [{"type": "text", "text": "Un immense merci à toute l'équipe de la radio pour son accueil chaleureux et pour avoir donné une voix à la science sur les ondes."}]}]}$q$::jsonb, $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "We had the pleasure of spending our evening in the studios of "}, {"type": "text", "text": "Radio Tlemcen", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — an incredible opportunity for the club to step behind the microphone and share our passion with a wider audience."}]}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/6d70717a-61b3-53ab-b580-10f1509116c7/c97d6482-367c-5079-9a16-954c8e96856d.webp", "alt": "The club on air at Radio Tlemcen — photo 1", "caption": "", "mediaId": "c97d6482-367c-5079-9a16-954c8e96856d"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/6d70717a-61b3-53ab-b580-10f1509116c7/290cfe87-ad4f-505c-a23a-ab612cc87314.webp", "alt": "The club on air at Radio Tlemcen — photo 2", "caption": "", "mediaId": "290cfe87-ad4f-505c-a23a-ab612cc87314"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/6d70717a-61b3-53ab-b580-10f1509116c7/f00dd696-614c-5795-907e-7cd19a205fb8.webp", "alt": "The club on air at Radio Tlemcen — photo 3", "caption": "", "mediaId": "f00dd696-614c-5795-907e-7cd19a205fb8"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/6d70717a-61b3-53ab-b580-10f1509116c7/b7eec27e-7b3d-5015-b5cb-f98548a3567a.webp", "alt": "The club on air at Radio Tlemcen — photo 4", "caption": "", "mediaId": "b7eec27e-7b3d-5015-b5cb-f98548a3567a"}], "layout": "grid", "columns": 2}}, {"type": "paragraph", "content": [{"type": "text", "text": "A huge thank you to the whole radio team for the warm welcome and for giving science a voice on the airwaves."}]}]}$q$::jsonb, $q${"instagram": "https://www.instagram.com/p/DXDLOJtCNXU/"}$q$::jsonb, 'draft')
