values ($q$12504a76-2308-576f-9480-dfe694eeab25$q$, $q$moqawil-2025$q$, $q$Moqawil — Le club présente son stand et son atelier$q$, $q$Moqawil — The club presents its stand and workshop$q$, $q$Participation du Life Savers Club à l'événement Moqawil à l'École supérieure de management de Tlemcen.$q$, $q$Life Savers Club took part in the Moqawil event at the École Supérieure de Management in Tlemcen.$q$, $q$École supérieure de management, Tlemcen$q$, $q$2025-04-26 09:00+01$q$, null, $q$https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/843f58cc-fe07-5c72-a301-136214497606.webp$q$, $q$Des membres du club en blouse devant le stand Life Savers à Moqawil$q$, $q${"x": 50, "y": 45}$q$::jsonb, $q${}$q$::jsonb, false, 0, $q$[]$q$::jsonb, array[$q$Salon$q$, $q$Vie du club$q$]::text[], $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nous avons eu l'honneur de participer à l'événement "}, {"type": "text", "text": "Moqawil", "marks": [{"type": "bold"}]}, {"type": "text", "text": " à l'École supérieure de management de Tlemcen, où nous avons présenté notre club et notre atelier santé : prise de tension, supports pédagogiques sur les organes et échanges avec les visiteurs."}]}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/66b0392d-3d34-522b-8fc3-1528fc656551-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/f02530b1-3435-59a1-bc74-f2b8af006c27.webp", "title": "Moqawil en vidéo", "caption": "", "loop": false}}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/80053913-85f8-54b7-95e3-6d320bf1a66b.webp", "alt": "Moqawil — photo 1", "caption": "", "mediaId": "80053913-85f8-54b7-95e3-6d320bf1a66b"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/fe0259ec-0d02-5fe5-ae2d-01448e6a4cbe.webp", "alt": "Moqawil — photo 2", "caption": "", "mediaId": "fe0259ec-0d02-5fe5-ae2d-01448e6a4cbe"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/f02530b1-3435-59a1-bc74-f2b8af006c27.webp", "alt": "Moqawil — photo 3", "caption": "", "mediaId": "f02530b1-3435-59a1-bc74-f2b8af006c27"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/fbec051f-c3b6-52e9-b8bc-d91d6f2de625.webp", "alt": "Moqawil — photo 4", "caption": "", "mediaId": "fbec051f-c3b6-52e9-b8bc-d91d6f2de625"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/eba153ee-e0c4-55cd-85d9-68cdce3005ee.webp", "alt": "Moqawil — photo 5", "caption": "", "mediaId": "eba153ee-e0c4-55cd-85d9-68cdce3005ee"}], "layout": "grid", "columns": 3}}, {"type": "paragraph", "content": [{"type": "text", "text": "Merci pour cette belle opportunité, et un grand bravo aux membres présents pour leur excellent travail !"}]}]}$q$::jsonb, $q${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "We had the honour of taking part in the "}, {"type": "text", "text": "Moqawil", "marks": [{"type": "bold"}]}, {"type": "text", "text": " event at the École Supérieure de Management in Tlemcen, where we presented our club and our health workshop: blood pressure checks, teaching materials on the organs and conversations with visitors."}]}, {"type": "video", "attrs": {"provider": "file", "src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/66b0392d-3d34-522b-8fc3-1528fc656551-v2.mp4", "poster": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/f02530b1-3435-59a1-bc74-f2b8af006c27.webp", "title": "Moqawil on video", "caption": "", "loop": false}}, {"type": "gallery", "attrs": {"images": [{"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/80053913-85f8-54b7-95e3-6d320bf1a66b.webp", "alt": "Moqawil — photo 1", "caption": "", "mediaId": "80053913-85f8-54b7-95e3-6d320bf1a66b"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/fe0259ec-0d02-5fe5-ae2d-01448e6a4cbe.webp", "alt": "Moqawil — photo 2", "caption": "", "mediaId": "fe0259ec-0d02-5fe5-ae2d-01448e6a4cbe"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/f02530b1-3435-59a1-bc74-f2b8af006c27.webp", "alt": "Moqawil — photo 3", "caption": "", "mediaId": "f02530b1-3435-59a1-bc74-f2b8af006c27"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/fbec051f-c3b6-52e9-b8bc-d91d6f2de625.webp", "alt": "Moqawil — photo 4", "caption": "", "mediaId": "fbec051f-c3b6-52e9-b8bc-d91d6f2de625"}, {"src": "https://kvqcnvbdzqxmvffipkui.supabase.co/storage/v1/object/public/event-media/events/12504a76-2308-576f-9480-dfe694eeab25/eba153ee-e0c4-55cd-85d9-68cdce3005ee.webp", "alt": "Moqawil — photo 5", "caption": "", "mediaId": "eba153ee-e0c4-55cd-85d9-68cdce3005ee"}], "layout": "grid", "columns": 3}}, {"type": "paragraph", "content": [{"type": "text", "text": "Thank you for this great opportunity, and well done to the members who were there for their excellent work!"}]}]}$q$::jsonb, $q${"instagram": "https://www.instagram.com/reel/DI68DU6tugR/"}$q$::jsonb, 'draft')
